def get_link_transforms(joint_pos):
    """Computes cumulative link frames."""
    T = np.eye(4)
    transforms = [T]
    for i, (d, a, alpha) in enumerate(DH_PARAMS):
        theta = joint_pos[i]
        ct, st = np.cos(theta), np.sin(theta)
        ca, sa = np.cos(alpha), np.sin(alpha)
        dh_matrix = np.array([
            [ct, -st*ca,  st*sa, a*ct],
            [st,  ct*ca, -ct*sa, a*st],
            [0,   sa,     ca,    d],
            [0,   0,      0,     1]
        ])
        T = T @ dh_matrix
        transforms.append(T)
    return transforms

