#FOR BREATHING, THESE ARE NOT TRUE KINEMATIC CHAINS, FIRST(BASE) JOINT IS OMITTED FOR BREATHING CALCULATIONS 
#                  (TESSEKKURLER MUSTAFA AKBABA)

def shoulder_to_base_translation(joint_pos):
    
    theta2 = joint_pos[1]
    theta3 = joint_pos[2]
    
    Tr = np.zeros(3)
    Tr[0] = - (1961*cos(theta2 + theta3))/5000 - (17*cos(theta2))/40
    Tr[1] = - (3896709061456873*sin(theta2 + theta3))/162259276829213363391578010288128 - (1055648490004571*sin(theta2))/40564819207303340847894502572032
    Tr[2] = 13/80 - (17*sin(theta2))/40 - (1961*sin(theta2 + theta3))/5000
    
    return Tr

def shoulder_to_base_translation_x_z(joint_pos):
    
    theta2 = joint_pos[1]
    theta3 = joint_pos[2]
    
    Tr = np.zeros(2)
    Tr[0] = - (1961*cos(theta2 + theta3))/5000 - (17*cos(theta2))/40
    Tr[1] = 13/80 - (17*sin(theta2))/40 - (1961*sin(theta2 + theta3))/5000
    
    return Tr

def shoulder_to_base_rotation(joint_pos):
    
    theta2 = joint_pos[1]
    theta3 = joint_pos[2]
    
    Rr = np.zeros((3,3))    
    Rr[0,0] = cos(theta2 + theta3)
    Rr[0,1] = -sin(theta2 + theta3)
    Rr[0,2] = 0
    Rr[1,0] = 0
    Rr[1,1] = 0
    Rr[1,2] = -1
    Rr[2,0] = sin(theta2 + theta3)
    Rr[2,1] = cos(theta2 + theta3)
    Rr[2,2] = 0
    
    return Rr

def shoulder_to_base_jacobian(joint_pos):
    """

        ONLY TRANSLATIONAL OF X AND Z AXIS IS CONSIDERED FOR BREATHING CALCULATIONS
    
    """
    
    theta2 = joint_pos[1]
    theta3 = joint_pos[2]
    
    #discarding unnecessary dimensions so it is reversible
    J = np.zeros((2,2))
    J[0,0] = (1961*sin(theta2 + theta3))/5000 + (17*sin(theta2))/40
    J[0,1] = (1961*sin(theta2 + theta3))/5000
    J[1,0] = - (1961*cos(theta2 + theta3))/5000 - (17*cos(theta2))/40
    J[1,1] = -(1961*cos(theta2 + theta3))/5000
    #J[3,0] = 0
    #J[3,1] = 0
    #J[4,0] = -1
    #J[4,1] = -1
    #J[5,0] = 0
    #J[5,1] = 0
    
    return J